    /// Returns information about the current localization target. This is an offline method if only_local is true. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.LocalizationTargetInfo> GetLocalizationTargetInfoAsync(bool onlyLocal = default)
    {

           using var activity =  StartCallActivity("GetLocalizationTargetInfoAsync", typeof(GetLocalizationTargetInfo).FullName ?? "GetLocalizationTargetInfoAsync");

           try
           {
             return client.GetLocalizationTargetInfoAsync(onlyLocal);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
